{"content":"import sys, numpy as np, torch
from types import SimpleNamespace
sys.path.insert(0, "/home/wlia0047/ar57/wenyu/GeneRec/results/research/issue121/trees/round_20261028_125823_958/fork-angle-transport")
from model.model import RQVAE
emb = np.load("/home/wlia0047/ar57/wenyu/GeneRec/stage1_GeneEmbedding/output/sentence_t5.npy").astype("float32")
cfg = SimpleNamespace(hidden_sizes=(512,256,128), codebook_num=3, codebook_size=(256,256,256),
                      codebook_dim=32, beta=0.25, dropout=0.0, vq_type="vq",
                      sk_epsilon=0.003, sk_iters=50, ema_decay=0.99, fix_code_embs=False)
def build():
    torch.manual_seed(0)
    m = RQVAE(cfg, in_dim=emb.shape[1])
    for mod in m.modules():
        if isinstance(mod, torch.nn.Linear):
            torch.nn.init.xavier_normal_(mod.weight)
            if mod.bias is not None: torch.nn.init.zeros_(mod.bias)
    return m
allx = torch.from_numpy(emb); x = allx[:512]
ids = torch.randint(512, 24587, (512, 8))
for label, make_ctx in [("baseline(no ctx)", False), ("candidate both_on", True), ("behaviour_off", True), ("geometry_off", True)]:
    m = build()
    with torch.no_grad():
        m.init_codebook(x); mean = m.encoder(allx[ids]).mean(1)
    ctx = None
    if make_ctx:
        ctx = {"neighbour_mean": mean, "scale": torch.full((512,), 0.6), "curvature": 1.0, "geometry_on": label != "geometry_off"}
        if label == "behaviour_off":
            ctx = {"neighbour_mean": torch.zeros(512,32), "scale": torch.zeros(512), "curvature": 1.0, "geometry_on": True}
    m.train(); m.zero_grad(set_to_none=True)
    r, q, _, _ = m(x, fork_context=ctx)
    l, rl = m.compute_loss(x, r, q); l.backward()
    tot = torch.sqrt(sum((p.grad.detach()**2).sum() for p in m.parameters() if p.grad is not None))
    print("%-18s loss %.6f recon %.8f | total grad norm %.3f -> clip factor %.4f" % (label, l, rl, tot, min(1.0, 1.0/float(tot))))
